const http = require('http'), fs = require('fs'), path = require('path'), crypto = require('crypto'), zlib = require('zlib');
const { spawn } = require('child_process');

// Load .env from the same folder (no dependency). Real env vars win.
try { for (const l of fs.readFileSync(path.join(__dirname, '.env'), 'utf8').split(/\r?\n/)) {
  const m = /^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*?)\s*$/.exec(l); if (!m || l.trim().startsWith('#')) continue;
  const v = m[2].replace(/^(['"])(.*)\1$/, '$2'); if (v && process.env[m[1]] === undefined) process.env[m[1]] = v; } } catch {}

// ffmpeg (optional, from the ffmpeg-static npm package): put it on PATH so Codex can process video/audio.
let HAVE_FFMPEG = false;
try { const ff = require('ffmpeg-static'); if (ff && fs.existsSync(ff)) { process.env.PATH = path.dirname(ff) + path.delimiter + process.env.PATH; HAVE_FFMPEG = path.basename(ff) === 'ffmpeg'; } } catch {}

const PORT = +process.env.APP_PORT || +process.env.SERVER_PORT || +process.env.PORT || 3000;
const PASSWORD = process.env.APP_PASSWORD || 'motu';  // <-- apna password yaha badlo
if (!PASSWORD) { console.error('Set APP_PASSWORD env variable'); process.exit(1); }

const ROOT = path.join(__dirname, 'workspace');
const LOGS = path.join(__dirname, 'logs');
fs.mkdirSync(ROOT, { recursive: true });
fs.mkdirSync(LOGS, { recursive: true });

const local = path.join(__dirname, 'node_modules', '.bin', 'codex');
let CODEX = process.env.CODEX_BIN || (fs.existsSync(local) ? local : 'codex');
if (CODEX.includes('/')) CODEX = path.resolve(__dirname, CODEX); // relative paths are relative to this folder, not the project dir
// Container is already the sandbox, so Codex's own sandbox (landlock) is bypassed by default.
// If you want it back: CODEX_FLAGS="--full-auto --skip-git-repo-check"
const FLAGS = (process.env.CODEX_FLAGS || '--dangerously-bypass-approvals-and-sandbox --skip-git-repo-check').split(' ').filter(Boolean);

const TOKEN = crypto.createHmac('sha256', PASSWORD).update('codex-web-session').digest('hex');
const safeEq = (a, b) => { const x = Buffer.from(a), y = Buffer.from(b); return x.length === y.length && crypto.timingSafeEqual(x, y); };
const isAuthed = req => { const m = /(?:^|;\s*)cw=([a-f0-9]+)/.exec(req.headers.cookie || ''); return !!m && safeEq(m[1], TOKEN); };

// ---- jobs (run on the server, independent of the browser) ----
const jobs = new Map();
for (const f of fs.readdirSync(LOGS).filter(f => f.endsWith('.json'))) {
  try { const j = JSON.parse(fs.readFileSync(path.join(LOGS, f))); j.log = []; j.clients = new Set(); jobs.set(j.id, j); } catch {}
}
const saveMeta = j => fs.writeFileSync(path.join(LOGS, j.id + '.json'), JSON.stringify({ id: j.id, project: j.project, prompt: j.prompt, status: j.status, start: j.start, end: j.end }));
const logPath = j => path.join(LOGS, j.id + '.log');
const pub = j => ({ id: j.id, project: j.project, prompt: j.prompt.slice(0, 140), status: j.status, start: j.start, end: j.end });
const emit = (j, ev, data) => { for (const r of j.clients) r.write(`event: ${ev}\ndata: ${JSON.stringify(data)}\n\n`); };

function startJob(project, prompt, cont) {
  const id = Date.now().toString(36) + crypto.randomBytes(2).toString('hex');
  const dir = path.join(ROOT, project);
  fs.mkdirSync(dir, { recursive: true });
  const j = { id, project, prompt, status: 'running', start: Date.now(), end: null, log: [], clients: new Set(), proc: null };
  jobs.set(id, j);
  const args = cont ? ['exec', ...FLAGS, 'resume', '--last', prompt] : ['exec', ...FLAGS, prompt];
  const push = t => { const s = t.toString(); j.log.push(s); fs.appendFileSync(logPath(j), s); emit(j, 'out', s); };
  push(`$ codex ${cont ? 'exec resume --last' : 'exec'} (project: ${project})\n\n`);
  try {
    j.proc = spawn(CODEX, args, { cwd: dir, env: process.env, stdio: ['ignore', 'pipe', 'pipe'] });
  } catch (e) { push('spawn error: ' + e.message + '\n'); finish(j, 'failed'); return j; }
  j.proc.stdout.on('data', push);
  j.proc.stderr.on('data', push);
  j.proc.on('error', e => { push('\nerror: ' + e.message + '\n(Codex installed? Check npm install finished.)\n'); finish(j, 'failed'); });
  j.proc.on('close', code => { if (j.status === 'running') finish(j, code === 0 ? 'done' : 'failed'); });
  saveMeta(j);
  return j;
}
function finish(j, status) {
  if (j.end) return;
  j.status = status; j.end = Date.now(); saveMeta(j);
  emit(j, 'done', status);
  for (const r of j.clients) r.end();
  j.clients.clear();
}

// ---- full interactive terminal (real Codex TUI in browser, stays alive 24/7) ----
// Uses `script` (util-linux) to give Codex a real PTY, so no native modules are needed.
const term = { proc: null, mode: null, buf: Buffer.alloc(0), clients: new Set() };
const shq = s => "'" + String(s).replace(/'/g, "'\\''") + "'";
function termStart(mode, cols, rows, project) {
  if (term.proc) return;
  cols = Math.min(Math.max(+cols || 80, 20), 400); rows = Math.min(Math.max(+rows || 24, 5), 200);
  const dir = path.join(ROOT, okName(project) ? project : 'terminal');
  fs.mkdirSync(dir, { recursive: true });
  const cmd = mode === 'bash' ? 'exec bash' : 'exec ' + [CODEX, ...FLAGS.filter(f => f !== '--skip-git-repo-check')].map(shq).join(' ');
  term.mode = mode; term.buf = Buffer.alloc(0);
  term.proc = spawn('script', ['-qfc', `stty cols ${cols} rows ${rows}; ${cmd}`, '/dev/null'],
    { cwd: dir, env: { ...process.env, TERM: 'xterm-256color', COLORTERM: 'truecolor' }, stdio: ['pipe', 'pipe', 'pipe'] });
  const out = d => {
    term.buf = Buffer.concat([term.buf, d]); if (term.buf.length > 300000) term.buf = term.buf.slice(-200000);
    for (const r of term.clients) r.write(`event: d\ndata: ${d.toString('base64')}\n\n`);
  };
  term.proc.stdout.on('data', out); term.proc.stderr.on('data', out);
  const end = msg => { if (!term.proc) return; term.proc = null; out(Buffer.from('\r\n[' + msg + ']\r\n')); for (const r of term.clients) r.write('event: exit\ndata: 1\n\n'); };
  term.proc.on('error', e => end('cannot start: ' + e.message + ' (is `script` installed?)'));
  term.proc.on('close', c => end('session ended (' + c + ')'));
}

// ---- http helpers ----
const json = (res, code, obj) => { res.writeHead(code, { 'Content-Type': 'application/json' }); res.end(JSON.stringify(obj)); return true; };
const body = req => new Promise(resolve => {
  let d = ''; req.on('data', c => { d += c; if (d.length > 1e6) req.destroy(); });
  req.on('end', () => { try { resolve(JSON.parse(d || '{}')); } catch { resolve({}); } });
});
const okName = n => typeof n === 'string' && /^[a-zA-Z0-9_-]{1,40}$/.test(n);
const fails = new Map();

// ---- chat mode: messages, uploads (incl. images), downloads, zip ----
const CHATS = path.join(__dirname, 'chats'); fs.mkdirSync(CHATS, { recursive: true });
const chatCache = new Map(), chatRuns = new Map();
const IMG = /\.(png|jpe?g|gif|webp|bmp)$/i;
const chatFile = p => path.join(CHATS, p + '.json');
function loadChat(p) {
  if (chatCache.has(p)) return chatCache.get(p);
  let c; try { c = JSON.parse(fs.readFileSync(chatFile(p), 'utf8')); } catch { c = { messages: [], resume: false }; }
  if (!chatRuns.has(p)) for (const m of c.messages) if (m.status === 'running') { m.status = 'failed'; m.text = m.text || '(server restarted while running)'; }
  chatCache.set(p, c); return c;
}
function saveChat(p) { const c = loadChat(p); if (c.messages.length > 300) c.messages = c.messages.slice(-300); fs.writeFileSync(chatFile(p), JSON.stringify(c)); }
const safeName = n => path.basename(String(n || 'file')).replace(/[^\w.\- ()]/g, '_').slice(0, 100) || 'file';
const inside = (base, rel) => { const f = path.resolve(base, String(rel || '')); return (f === base || f.startsWith(base + path.sep)) ? f : null; };
const SKIP = new Set(['node_modules', '__pycache__']);
function walk(dir, base = dir, out = [], depth = 0) {
  if (out.length > 2000 || depth > 8) return out;
  let ents; try { ents = fs.readdirSync(dir, { withFileTypes: true }); } catch { return out; }
  for (const e of ents) {
    if (SKIP.has(e.name) || e.name.startsWith('.')) continue;
    const f = path.join(dir, e.name);
    if (e.isDirectory()) walk(f, base, out, depth + 1);
    else if (e.isFile()) { const st = fs.statSync(f); out.push({ path: path.relative(base, f).split(path.sep).join('/'), size: st.size, mtime: Math.floor(st.mtimeMs) }); }
  }
  return out;
}
const snap = dir => new Map(walk(dir).map(f => [f.path, f.size + ':' + f.mtime]));

const CRC = (() => { const t = []; for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
const crc32 = b => { let c = 0xFFFFFFFF; for (let i = 0; i < b.length; i++) c = CRC[(c ^ b[i]) & 255] ^ (c >>> 8); return (c ^ 0xFFFFFFFF) >>> 0; };
function makeZip(files) {
  const parts = [], cd = []; let off = 0;
  for (const f of files) {
    const nb = Buffer.from(f.name), raw = f.data, comp = zlib.deflateRawSync(raw), crc = crc32(raw);
    const lh = Buffer.alloc(30);
    lh.writeUInt32LE(0x04034b50, 0); lh.writeUInt16LE(20, 4); lh.writeUInt16LE(0x0800, 6); lh.writeUInt16LE(8, 8);
    lh.writeUInt16LE(0, 10); lh.writeUInt16LE(0x21, 12); lh.writeUInt32LE(crc, 14); lh.writeUInt32LE(comp.length, 18);
    lh.writeUInt32LE(raw.length, 22); lh.writeUInt16LE(nb.length, 26);
    parts.push(lh, nb, comp);
    const ch = Buffer.alloc(46);
    ch.writeUInt32LE(0x02014b50, 0); ch.writeUInt16LE(20, 4); ch.writeUInt16LE(20, 6); ch.writeUInt16LE(0x0800, 8); ch.writeUInt16LE(8, 10);
    ch.writeUInt16LE(0, 12); ch.writeUInt16LE(0x21, 14); ch.writeUInt32LE(crc, 16); ch.writeUInt32LE(comp.length, 20);
    ch.writeUInt32LE(raw.length, 24); ch.writeUInt16LE(nb.length, 28); ch.writeUInt32LE(off, 42);
    cd.push(ch, nb); off += 30 + nb.length + comp.length;
  }
  const cdb = Buffer.concat(cd), end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0); end.writeUInt16LE(files.length, 8); end.writeUInt16LE(files.length, 10);
  end.writeUInt32LE(cdb.length, 12); end.writeUInt32LE(off, 16);
  return Buffer.concat([...parts, cdb, end]);
}

function runCodex(dir, args, prompt, onData, setProc) {
  return new Promise(resolve => {
    let proc;
    try { proc = spawn(CODEX, args, { cwd: dir, env: process.env, stdio: ['pipe', 'pipe', 'pipe'] }); }
    catch (e) { return resolve({ code: -1, out: String(e.message) }); }
    setProc(proc); let out = '';
    const d = b => { const s = b.toString(); out += s; onData(s); };
    proc.stdout.on('data', d); proc.stderr.on('data', d);
    proc.stdin.on('error', () => {}); proc.stdin.end(prompt);
    proc.on('error', e => resolve({ code: -1, out: out + '\n' + e.message }));
    proc.on('close', code => resolve({ code, out }));
  });
}

// ---- "who made you?" -> fixed branded answer (no Codex call needed) ----
const CREATOR_REPLY = 'This is AI code made by **Motu Patlu** 🛠️\n\n- Telegram: [@MOTU_PATALU_HINDU_HAI](https://t.me/MOTU_PATALU_HINDU_HAI)\n- Channel: https://t.me/Dev_Null_X_NODE_JS\n- YouTube: https://www.youtube.com/@Dev_Null_X';
function isCreatorQ(t) {
  t = String(t || '').toLowerCase().trim();
  if (!t || t.length > 160) return false;
  if (/\b(file|function|script|class|module|likha|likhi|repo|line)\b/.test(t)) return false;
  const you = /(\btum\w*|\btu\b|\btujh\w*|\baap\w*|\bap\b|\bapko\b|\byou\b|\bu\b|\byour\b|\bur\b|\bai\b|\bbot\b|\bapp\b|\bsite\b|\bwebsite\b|\byeh\b|\bye\b|तुम|आप|तू|तुझे|यह|ये)/;
  const q = [/who\s+(made|created|built|developed|programmed|coded|designed|owns?|trained)\b/, /(your|ur)\s+(creator|developer|maker|owner|author)/,
    /made\s+by\s+who/, /\bk[ie]s\s*n[ie]\s*b[a]?n[a-z]*y?a/, /\bk(on|aun)\s+(ne\s+)?b[a]?n[a-z]*y?a/, /(creator|developer|owner|maker)\s+(kaun|kon|kya|ka\s+naam|name)/,
    /किसने\s*(तुम्हें|तुम्हे|आपको|इसे|इस)?\s*बनाया/, /कौन\s*(ने\s*)?बनाया/, /(बनाने\s*वाला|डेवलपर|मालिक)/];
  return you.test(t) && q.some(r => r.test(t));
}
function chatCanned(project, text) {
  const c = loadChat(project), id = Date.now().toString(36) + 'c';
  c.messages.push({ role: 'user', text, files: [], time: Date.now() }, { role: 'assistant', id, text: CREATOR_REPLY, status: 'done', time: Date.now(), end: Date.now(), changed: [] });
  saveChat(project); return id;
}

function chatSend(project, text, files) {
  const c = loadChat(project), dir = path.join(ROOT, project);
  fs.mkdirSync(dir, { recursive: true });
  const id = Date.now().toString(36) + crypto.randomBytes(2).toString('hex');
  const atts = (Array.isArray(files) ? files : []).filter(f => typeof f === 'string' && inside(dir, f) && fs.existsSync(path.join(dir, f)));
  const userMsg = { role: 'user', text, files: atts.map(f => ({ path: f, name: path.basename(f), image: IMG.test(f) })), time: Date.now() };
  const botMsg = { role: 'assistant', id, text: '', status: 'running', time: Date.now(), changed: [] };
  c.messages.push(userMsg, botMsg); saveChat(project);
  const run = { id, proc: null, log: [], stopped: false }; chatRuns.set(project, run);
  (async () => {
    const before = snap(dir), last = path.join(LOGS, id + '.last.txt');
    const imgArgs = atts.filter(f => IMG.test(f)).flatMap(f => ['-i', path.join(dir, f)]);
    const note = atts.length ? '\n\n[Attached files are in this folder: ' + atts.join(', ') + ']' : '';
    const prompt = (text || 'Please look at the attached files.') + note +
      '\n\n(Reply in the same language the user writes in. Save any files you create inside the current folder. ' + (HAVE_FFMPEG ? ' ffmpeg is installed on PATH: use it for video/audio tasks (extract frames or audio, trim, convert).' : '') + ' If the user asks who made or created you or this app, answer: "This is AI code made by Motu Patlu", with Telegram @MOTU_PATALU_HINDU_HAI, Channel https://t.me/Dev_Null_X_NODE_JS, YouTube https://www.youtube.com/@Dev_Null_X)';
    const onData = s => { run.log.push(s); if (run.log.length > 400) run.log.splice(0, 200); };
    const mk = resume => ['exec', ...imgArgs, '-o', last, ...FLAGS, ...(resume ? ['resume', '--last'] : [])];
    const setProc = p => { run.proc = p; };
    let r = null;
    if (c.resume) {
      r = await runCodex(dir, mk(true), prompt, onData, setProc);
      if (r.code !== 0 && !run.stopped && !fs.existsSync(last)) { onData('\n(could not resume, starting fresh with chat context)\n'); r = null; }
    }
    if (!r && !run.stopped) {
      const hist = c.messages.slice(0, -2).slice(-8).map(m => (m.role === 'user' ? 'User: ' : 'Assistant: ') + String(m.text || '').slice(0, 1500)).join('\n');
      r = await runCodex(dir, mk(false), hist ? 'Conversation so far:\n' + hist + '\n\nNew message from the user:\n' + prompt : prompt, onData, setProc);
    }
    r = r || { code: -1, out: '' };
    let reply = ''; try { reply = fs.readFileSync(last, 'utf8').trim(); fs.unlinkSync(last); } catch {}
    const after = snap(dir);
    botMsg.changed = [...after].filter(([k, v]) => !k.startsWith('uploads/') && before.get(k) !== v).map(([k]) => k).slice(0, 40);
    botMsg.status = run.stopped ? 'stopped' : (r.code === 0 ? 'done' : 'failed');
    if (r.code === 0 && !run.stopped) c.resume = true;
    botMsg.text = reply || (r.code === 0 ? '(no text reply)' : '');
    if (botMsg.status === 'failed') botMsg.text += (botMsg.text ? '\n\n' : '') + '⚠️ Error:\n```\n' + r.out.slice(-1500) + '\n```';
    if (botMsg.status === 'stopped' && !botMsg.text) botMsg.text = '(stopped)';
    botMsg.end = Date.now(); chatRuns.delete(project); saveChat(project);
  })().catch(e => { botMsg.status = 'failed'; botMsg.text = 'Internal error: ' + e.message; chatRuns.delete(project); saveChat(project); });
  return id;
}

const MIME = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', webp: 'image/webp', pdf: 'application/pdf', txt: 'text/plain; charset=utf-8', md: 'text/plain; charset=utf-8', json: 'text/plain; charset=utf-8', js: 'text/plain; charset=utf-8', py: 'text/plain; charset=utf-8', css: 'text/plain; charset=utf-8', html: 'text/plain; charset=utf-8' };

async function chatRoutes(req, res, url, p) {
  const q = k => url.searchParams.get(k);
  const project = q('project');
  if (p === '/api/upload' && req.method === 'POST') {
    if (!okName(project)) return json(res, 400, { error: 'project' });
    const dir = path.join(ROOT, project, 'uploads'); fs.mkdirSync(dir, { recursive: true });
    let name = safeName(q('name'));
    if (fs.existsSync(path.join(dir, name))) { const e = path.extname(name); name = path.basename(name, e) + '-' + Date.now().toString(36) + e; }
    const fp = path.join(dir, name), ws = fs.createWriteStream(fp); let n = 0, bad = false;
    req.on('data', c => { n += c.length; if (n > 60e6 && !bad) { bad = true; req.unpipe(ws); ws.destroy(); try { json(res, 413, { error: 'File too big (max 60MB)' }); } catch {} } });
    req.pipe(ws);
    ws.on('finish', () => { if (!bad) json(res, 200, { name, path: 'uploads/' + name, size: n, image: IMG.test(name) }); });
    ws.on('error', () => { try { json(res, 500, { error: 'upload failed' }); } catch {} });
    return true;
  }
  if (p === '/api/chat' && req.method === 'GET') {
    if (!okName(project)) return json(res, 400, { error: 'project' });
    const run = chatRuns.get(project);
    return json(res, 200, { messages: loadChat(project).messages, running: run ? run.id : null, activity: run ? run.log.join('').slice(-3000) : '' });
  }
  if (p === '/api/chat' && req.method === 'POST') {
    const b = await body(req);
    if (!okName(b.project)) return json(res, 400, { error: 'project' });
    const text = typeof b.text === 'string' ? b.text.trim().slice(0, 50000) : '';
    if (!text && !(b.files && b.files.length)) return json(res, 400, { error: 'Empty message' });
    if (chatRuns.has(b.project)) return json(res, 409, { error: 'Codex is still working on the previous message' });
    if (isCreatorQ(text) && !(b.files && b.files.length)) return json(res, 200, { id: chatCanned(b.project, text) });
    return json(res, 200, { id: chatSend(b.project, text, b.files) });
  }
  if (p === '/api/chat/stop' && req.method === 'POST') {
    const b = await body(req), run = chatRuns.get(b.project);
    if (run && run.proc) { run.stopped = true; const pr = run.proc; pr.kill('SIGTERM'); setTimeout(() => { try { pr.kill('SIGKILL'); } catch {} }, 3000); }
    return json(res, 200, { ok: true });
  }
  if (p === '/api/chat/new' && req.method === 'POST') {
    const b = await body(req);
    if (!okName(b.project) || chatRuns.has(b.project)) return json(res, 400, { error: 'busy or bad project' });
    const c = loadChat(b.project); c.messages = []; c.resume = false; saveChat(b.project);
    return json(res, 200, { ok: true });
  }
  if (p === '/api/tree') {
    if (!okName(project)) return json(res, 400, { error: 'project' });
    return json(res, 200, walk(path.join(ROOT, project)).sort((a, b) => a.path.localeCompare(b.path)));
  }
  if (p === '/api/file') {
    if (!okName(project)) return json(res, 400, { error: 'project' });
    const f = inside(path.join(ROOT, project), q('path'));
    if (!f || !fs.existsSync(f) || !fs.statSync(f).isFile()) return json(res, 404, { error: 'not found' });
    const ext = path.extname(f).slice(1).toLowerCase(), dl = q('dl') === '1' || !MIME[ext];
    const h = { 'Content-Type': dl ? 'application/octet-stream' : MIME[ext], 'X-Content-Type-Options': 'nosniff', 'Content-Length': fs.statSync(f).size };
    if (dl) h['Content-Disposition'] = 'attachment; filename="' + path.basename(f).replace(/"/g, '') + '"';
    res.writeHead(200, h); fs.createReadStream(f).pipe(res); return true;
  }
  if (p === '/api/zip') {
    if (!okName(project)) return json(res, 400, { error: 'project' });
    const base = path.join(ROOT, project); let rels;
    const job = q('job');
    if (job) { const m = loadChat(project).messages.find(m => m.id === job); rels = (m && m.changed) || []; }
    else rels = walk(base).map(f => f.path);
    const files = []; let total = 0;
    for (const r of rels) { const f = inside(base, r); if (!f || !fs.existsSync(f) || !fs.statSync(f).isFile()) continue; total += fs.statSync(f).size; if (total > 150e6) break; files.push({ name: r, data: fs.readFileSync(f) }); }
    if (!files.length) return json(res, 404, { error: 'No files' });
    const z = makeZip(files);
    res.writeHead(200, { 'Content-Type': 'application/zip', 'Content-Disposition': 'attachment; filename="' + project + (job ? '-files' : '') + '.zip"', 'Content-Length': z.length });
    res.end(z); return true;
  }
  return false;
}

http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://x');
  const p = url.pathname;

  if (req.method === 'POST' && p === '/login') {
    const ip = req.socket.remoteAddress, f = fails.get(ip) || { n: 0, t: 0 };
    if (f.n >= 5 && Date.now() - f.t < 60000) return json(res, 429, { error: 'Too many tries, wait 1 min' });
    const { password } = await body(req);
    if (typeof password === 'string' && safeEq(password, PASSWORD)) {
      fails.delete(ip);
      res.writeHead(200, { 'Content-Type': 'application/json', 'Set-Cookie': `cw=${TOKEN}; HttpOnly; SameSite=Strict; Path=/; Max-Age=2592000` });
      return res.end('{"ok":true}');
    }
    fails.set(ip, { n: f.n + 1, t: Date.now() });
    return json(res, 401, { error: 'Wrong password' });
  }

  if (p === '/') { res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' }); return res.end(CHATHTML); }
  if (p === '/jobs') { res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' }); return res.end(HTML); }
  if (p === '/term') { res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' }); return res.end(CHATHTML); }
  if (p === '/logout') { res.writeHead(302, { 'Set-Cookie': 'cw=; HttpOnly; SameSite=Strict; Path=/; Max-Age=0', Location: '/' }); return res.end(); }
  if (!isAuthed(req)) return json(res, 401, { error: 'auth' });

  if (await chatRoutes(req, res, url, p)) return;

  if (p === '/api/term/status') return json(res, 200, { running: !!term.proc, mode: term.mode });
  if (p === '/api/term/start' && req.method === 'POST') {
    const { mode, cols, rows, project } = await body(req);
    termStart(mode === 'bash' ? 'bash' : 'codex', cols, rows, project);
    return json(res, 200, { ok: true });
  }
  if (p === '/api/term/input' && req.method === 'POST') {
    const { data } = await body(req);
    if (term.proc && typeof data === 'string' && data.length < 100000) term.proc.stdin.write(data);
    return json(res, 200, { ok: true });
  }
  if (p === '/api/term/kill' && req.method === 'POST') {
    if (term.proc) { term.proc.kill('SIGTERM'); const pr = term.proc; setTimeout(() => pr.kill('SIGKILL'), 2000); }
    return json(res, 200, { ok: true });
  }
  if (p === '/api/term/stream') {
    res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache', Connection: 'keep-alive', 'X-Accel-Buffering': 'no' });
    if (term.buf.length) res.write(`event: d\ndata: ${term.buf.toString('base64')}\n\n`);
    term.clients.add(res);
    const ka = setInterval(() => res.write(': ka\n\n'), 20000);
    req.on('close', () => { clearInterval(ka); term.clients.delete(res); });
    return;
  }

  if (p === '/api/projects' && req.method === 'GET')
    return json(res, 200, fs.readdirSync(ROOT, { withFileTypes: true }).filter(d => d.isDirectory()).map(d => d.name));
  if (p === '/api/projects' && req.method === 'POST') {
    const { name } = await body(req);
    if (!okName(name)) return json(res, 400, { error: 'Name: letters, numbers, - _ (max 40)' });
    fs.mkdirSync(path.join(ROOT, name), { recursive: true });
    return json(res, 200, { ok: true });
  }
  if (p === '/api/jobs' && req.method === 'GET')
    return json(res, 200, [...jobs.values()].sort((a, b) => b.start - a.start).slice(0, 50).map(pub));
  if (p === '/api/jobs' && req.method === 'POST') {
    const { project, prompt, cont } = await body(req);
    if (!okName(project) || typeof prompt !== 'string' || !prompt.trim()) return json(res, 400, { error: 'Project and prompt needed' });
    return json(res, 200, pub(startJob(project, prompt.trim(), !!cont)));
  }
  let m = /^\/api\/jobs\/([a-z0-9]+)\/(stream|stop)$/.exec(p);
  if (m) {
    const j = jobs.get(m[1]);
    if (!j) return json(res, 404, { error: 'not found' });
    if (m[2] === 'stop') { if (j.proc && j.status === 'running') { j.status = 'stopped'; j.proc.kill('SIGTERM'); setTimeout(() => j.proc.kill('SIGKILL'), 3000); finish(j, 'stopped'); } return json(res, 200, { ok: true }); }
    res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache', Connection: 'keep-alive', 'X-Accel-Buffering': 'no' });
    const old = j.log.length ? j.log.join('') : (fs.existsSync(logPath(j)) ? fs.readFileSync(logPath(j), 'utf8') : '');
    res.write(`event: out\ndata: ${JSON.stringify(old)}\n\n`);
    if (j.end) { res.write(`event: done\ndata: ${JSON.stringify(j.status)}\n\n`); return res.end(); }
    j.clients.add(res);
    const ka = setInterval(() => res.write(': ka\n\n'), 20000);
    req.on('close', () => { clearInterval(ka); j.clients.delete(res); });
    return;
  }
  json(res, 404, { error: 'not found' });
}).listen(PORT, '0.0.0.0', () => console.log(`HX5X5X5X AI STUDIO running on port ${PORT} (codex: ${CODEX})`));

